/* Namaz təlimatı — gündəlik fərz namazını tək qılan, səfərdə olmayan şəxs üçün. */
const guidePrayers=[['Sübh',2],['Zöhr',4],['İkindi',4],['Məğrib',3],['İşa',4]];
const recitations={
 takbir:['Təkbir','اللَّهُ أَكْبَرُ','Allahu əkbər.','Allah ən böyükdür.'],
 subhanaka:['Sübhanəkə','سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ وَتَعَالَى جَدُّكَ وَلَا إِلَهَ غَيْرُكَ','Subhanəkəllahummə və bihəmdikə və təbarəkəsmukə və təalə cəddukə və lə ilahə ğayruk.','Allahım, Səni həmd ilə pak bilirəm. Adın mübarək, şanın ucadır. Səndən başqa ilah yoxdur.'],
 refuge:['Əuzu','أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ','Əuzu billəhi minəş-şeytanir-racim.','Qovulmuş şeytandan Allaha sığınıram.'],
 fatiha:['Fatihə surəsi','بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ۝ الرَّحْمَٰنِ الرَّحِيمِ ۝ مَالِكِ يَوْمِ الدِّينِ ۝ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ۝ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ','Bismilləhir-rahmənir-rahim. Əlhəmdu lilləhi rabbil-aləmin. Ər-rahmənir-rahim. Məliki yəvmid-din. İyyəkə nəbudu və iyyəkə nəstəin. İhdinəs-sıratal-mustəqim. Sıratalləzinə ənamtə aleyhim, ğayril-məğdubi aleyhim və ləd-dallin.','Rəhmli və mərhəmətli Allahın adı ilə. Həmd aləmlərin Rəbbi Allahadır. O, rəhmli və mərhəmətlidir, haqq-hesab gününün sahibidir. Yalnız Sənə ibadət edir və yalnız Səndən yardım istəyirik. Bizi doğru yola — nemət verdiklərinin yoluna yönəlt; qəzəbə düçar olmuşların və azmışların yoluna deyil.'],
 ikhlas:['İxlas surəsi','بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ ۝ قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ','Bismilləhir-rahmənir-rahim. Qul huvəllahu əhəd. Allahus-saməd. Ləm yəlid və ləm yuləd. Və ləm yəkun ləhu kufuvən əhəd.','De: Allah təkdir. Allah heç nəyə möhtac deyil, hər şey Ona möhtacdır. O, doğmamış və doğulmamışdır. Onun heç bir tayı yoxdur.'],
 rukuH:['Rüku zikri · 3 dəfə','سُبْحَانَ رَبِّيَ الْعَظِيمِ','Subhanə rabbiyəl-azim.','Uca Rəbbimi pak bilirəm.'],
 rukuJ:['Rüku zikri · 1 dəfə','سُبْحَانَ رَبِّيَ الْعَظِيمِ وَبِحَمْدِهِ','Subhanə rabbiyəl-azimi və bihəmdih.','Uca Rəbbimi həmd ilə pak bilirəm.'],
 rise:['Rükudan qalxarkən','سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ ۝ رَبَّنَا لَكَ الْحَمْدُ','Səmiallahu limən həmidəh. Rabbənə ləkəl-həmd.','Allah Ona həmd edəni eşidir. Rəbbimiz, həmd Sənədir.'],
 sujudH:['Səcdə zikri · 3 dəfə','سُبْحَانَ رَبِّيَ الْأَعْلَى','Subhanə rabbiyəl-əla.','Ən uca Rəbbimi pak bilirəm.'],
 sujudJ:['Səcdə zikri · 1 dəfə','سُبْحَانَ رَبِّيَ الْأَعْلَى وَبِحَمْدِهِ','Subhanə rabbiyəl-əla və bihəmdih.','Ən uca Rəbbimi həmd ilə pak bilirəm.'],
 tasbih:['Təsbihati-ərbəə','سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ','Subhanəllahi vəlhəmdu lilləhi və lə ilahə illəllahu vəllahu əkbər.','Allah pakdır, həmd Allahadır, Allahdan başqa ilah yoxdur və Allah ən böyükdür.'],
 tashH:['Əttəhiyyat','التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ','Əttəhiyyətu lilləhi vəs-saləvatu vət-tayyibət. Əssələmu aleykə əyyuhən-nəbiyyu və rahmətullahi və bərakətuh. Əssələmu aleynə və alə ibədilləhis-salihin. Əşhədu ən lə ilahə illəllah və əşhədu ənnə Muhammədən abduhu və rasuluh.','Bütün ehtiram, ibadət və gözəl sözlər Allahadır. Ey Peyğəmbər, sənə Allahın salamı, rəhməti və bərəkəti olsun. Bizə və Allahın saleh bəndələrinə salam olsun. Şəhadət edirəm ki, Allahdan başqa ilah yoxdur və Məhəmməd Onun qulu və elçisidir.'],
 tashJ:['Təşəhhüd','أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِ مُحَمَّدٍ','Əşhədu ən lə ilahə illəllahu vəhdəhu lə şərikə ləh. Və əşhədu ənnə Muhammədən abduhu və rasuluh. Allahummə salli alə Muhammədin və ali Muhamməd.','Şəhadət edirəm ki, Allah təkdir, şəriki yoxdur. Məhəmməd Onun qulu və elçisidir. Allahım, Məhəmmədə və onun ailəsinə salavat göndər.'],
 salawat:['Salli və Barik','اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ ۝ اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ','Allahummə salli alə Muhammədin və alə ali Muhamməd, kəmə salleytə alə İbrahimə və alə ali İbrahim, innəkə həmidun məcid. Allahummə barik alə Muhammədin və alə ali Muhamməd, kəmə barəktə alə İbrahimə və alə ali İbrahim, innəkə həmidun məcid.','Allahım! İbrahimə və ailəsinə göndərdiyin kimi Məhəmmədə və ailəsinə salavat və bərəkət göndər. Sən həmdə layiq və şanı ucasan.'],
 rabbana:['Rabbənə duası','رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ','Rabbənə ətinə fid-dunyə həsənətən və fil-axirəti həsənətən və qinə əzabən-nər.','Rəbbimiz! Bizə dünyada və axirətdə yaxşılıq ver, bizi od əzabından qoru.'],
 salamH:['Salam','السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ','Əssələmu aleykum və rahmətullah.','Sizə salam və Allahın rəhməti olsun.'],
 salamJ:['Salam','السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ','Əssələmu aleykum və rahmətullahi və bərakətuh.','Sizə salam, Allahın rəhməti və bərəkəti olsun.']
};
function guideState(){const s=read('nur-guide',{school:'hanafi',prayer:0,step:0});s.school=s.school==='jafari'?'jafari':'hanafi';s.prayer=Number.isInteger(s.prayer)&&s.prayer>=0&&s.prayer<5?s.prayer:0;return s}
function setGuide(k,v){let s=guideState();s[k]=k==='prayer'?Number(v):v;s.step=0;save('nur-guide',s);render()}
function guideSteps(s){const j=s.school==='jafari',count=guidePrayers[s.prayer][1],steps=[];const add=(r,title,body,pose,rec=[],tag='')=>steps.push({r,title,body,pose,rec,tag});
 add(0,'Hazırlıq və niyyət',`${guidePrayers[s.prayer][0]} namazının ${count} rükət fərzini Allah üçün qılmağa ürəkdən niyyət edin. Dəstəmazlı, təmiz və örtülü halda, vaxt daxil olduqdan sonra qibləyə yönəlin. Niyyəti dillə demək şərt deyil.`,'stand');
 add(1,'Başlanğıc təkbiri',j?'Ayaq üstə, bədən sakit ikən təkbiri deyin. Sonra əlləri yanlarda sərbəst saxlayın.':'Təkbir deyərək əlləri qaldırın, sonra sağ əli solun üstünə qoyun. Kişilər əlləri göbək altında, qadınlar sinə üzərində bağlayırlar.','takbir',['takbir']);
 for(let r=1;r<=count;r++){
  const first=r<=2;
  if(r>1)add(r,'Qiyama qalxın',j?'İkinci səcdədən sonra sakitcə oturun, sonra növbəti rükətə qalxın.':'“Allahu əkbər” deyərək ayağa qalxın.','stand');
  if(first){if(r===1&&!j)add(r,'Başlanğıc oxunuşu','Ayaq üstə Sübhanəkə və Əuzu oxuyun.','stand',['subhanaka','refuge'],'Sünnə');
   add(r,'Fatihə və İxlas',j?'Bismillah daxil olmaqla Fatihəni, ardınca tam İxlas surəsini oxuyun. “Amin” deməyin.':'Bismillah ilə Fatihəni oxuyun, sonunda sakitcə “Amin” deyin. Ardınca İxlası oxuyun. Başqa uyğun surə də seçilə bilər.','stand',['fatiha','ikhlas']);
   if(r===2&&j)add(r,'Qunut','Rükudan əvvəl ovucları yuxarı tutaraq dua edin. Aşağıdakı Rabbənə duası bir nümunədir. Qunut müstəhəbdir.','qunut',['rabbana'],'Müstəhəb');
  }else add(r,j?'Təsbihati-ərbəə':'Fatihə',j?'Ayaq üstə aşağıdakı zikri asta səslə bir dəfə deyin; üç dəfə demək daha fəzilətlidir. Alternativ olaraq yalnız Fatihə oxuna bilər.':'Bismillah ilə yalnız Fatihəni oxuyun; fərzin üçüncü və dördüncü rükətində əlavə surə oxunmur.','stand',j?['tasbih']:['fatiha']);
  add(r,'Rüku',j?'Əllər dizlərə çatacaq qədər əyilin. Bədən sakitləşdikdə zikri bir dəfə deyin.':'“Allahu əkbər” deyərək əyilin, əlləri dizlərə qoyun. Aşağıdakı zikri üç dəfə deyin.','bow',[j?'rukuJ':'rukuH']);
  add(r,'Rükudan doğrulun',j?'Tam dikəlin, ayaq üstə bədən sakitləşənədək dayanın.':'“Səmiallahu limən həmidəh” deyərək dikəlin, sonra “Rabbənə ləkəl-həmd” deyin. Bədən sakitləşsin.','stand',j?[]:['rise']);
  const sujud=j?'Alın, iki ovuc, iki diz və iki ayağın baş barmağı yerə dəysin. Alın təmiz, səcdəyə yararlı səthə, məsələn torpaq möhürə qoyulur. Sakit halda zikri bir dəfə deyin.':'“Allahu əkbər” deyərək səcdəyə gedin. Alın və burun, əllər, dizlər və ayaq barmaqları yerə dəysin. Sakit halda zikri üç dəfə deyin.';
  add(r,'Birinci səcdə',sujud,'prostrate',[j?'sujudJ':'sujudH']);
  add(r,'İki səcdə arasında oturuş',j?'Başınızı qaldırıb oturun və bədəniniz sakitləşsin.':'“Allahu əkbər” deyib başınızı qaldırın. Oturun və bədəniniz sakitləşsin.','sit');
  add(r,'İkinci səcdə',j?'Yenidən səcdə edin. Birinci səcdədəki təmas nöqtələrini qoruyaraq, sakit halda eyni zikri bir dəfə deyin.':'“Allahu əkbər” deyib yenidən səcdə edin. Eyni zikri üç dəfə deyin.','prostrate',[j?'sujudJ':'sujudH']);
  if(r===2||r===count){add(r,j?'Təşəhhüd':'Oturuş və Əttəhiyyat',r===count?'İkinci səcdədən qalxıb oturun və aşağıdakı mətni oxuyun.':'İkinci səcdədən qalxıb oturun, aşağıdakı mətni oxuyun. Bu ara oturuşdur: salam vermədən növbəti rükətə keçəcəksiniz.','sit',[j?'tashJ':'tashH']);}
  if(r===count){if(!j)add(r,'Salavat və dua','Son oturuşda Əttəhiyyatdan sonra Salli, Barik və Rabbənə duasını oxuyun.','sit',['salawat','rabbana'],'Sünnə');add(r,'Salam və tamamlanma',j?'Oturaq və sakit halda aşağıdakı salamı deyin. Bu, namazı bitirən kifayət edən salam formasıdır.':'Əvvəl başınızı sağa, sonra sola çevirərək hər tərəfə aşağıdakı salamı deyin.','sit',[j?'salamJ':'salamH']);}
 }
 return steps;
}
function posture(p){const shapes={stand:'<circle cx="100" cy="35" r="13"/><path d="M100 52v68m0 0-21 58m21-58 21 58M96 64 79 105m25-41 17 41"/>',takbir:'<circle cx="100" cy="35" r="13"/><path d="M100 52v68m0 0-21 58m21-58 21 58M96 64 72 77 65 44m39 20 24 13 7-33"/>',qunut:'<circle cx="100" cy="35" r="13"/><path d="M100 52v68m0 0-21 58m21-58 21 58M96 64 74 95 88 77m16-13 22 31-14-18"/>',bow:'<circle cx="145" cy="78" r="13"/><path d="M128 78H79l-5 50-7 50m13-50 17 50m21-100 12 43-48 7"/>',sit:'<circle cx="99" cy="60" r="13"/><path d="M99 77v52l-34 31 63 8m-29-91 15 47-39 24m-10 12 49 18h28"/>',prostrate:'<circle cx="151" cy="151" r="13"/><path d="m137 142-42-39-34 53-25 15h53m20-54 7 49h35m-90-10 28 15"/>'};return `<svg viewBox="0 0 200 200" class="posture" role="img" aria-label="${({stand:'Qiyam',takbir:'Təkbir',qunut:'Qunut',bow:'Rüku',sit:'Oturuş',prostrate:'Səcdə'})[p]}"><ellipse cx="100" cy="185" rx="83" ry="7" fill="#bca36b22"/><g fill="none" stroke="currentColor" stroke-width="6" stroke-linecap="round" stroke-linejoin="round">${shapes[p]||shapes.stand}</g></svg>`}
function recitationCard(id){const d=recitations[id];return `<section class="recite"><h3>${d[0]}</h3><p class="arabic" lang="ar" dir="rtl">${d[1]}</p><details><summary>Oxunuşu və mənası</summary><p class="translit">${d[2]}</p><p class="muted">${d[3]}</p></details></section>`}
function preparation(j){return `<details class="guide-details"><summary>Dəstəmaz və namaza hazırlıq</summary><p>Təmiz su istifadə edin; suyun dəriyə çatmasına mane olan örtüyü aradan qaldırın. Qüsl tələb edən halda təkcə dəstəmaz kifayət etmir.</p>${j?'<ol><li>Niyyət edin və üzü saç bitən yerdən çənəyədək, baş və orta barmağın əhatə etdiyi en daxilində yuxarıdan aşağı yuyun.</li><li>Əvvəl sağ, sonra sol qolu dirsəkdən barmaq uclarınadək yuyun; dirsəklər də yuyulsun.</li><li>Dəstəmazdan qalan əl rütubəti ilə başın ön hissəsinə məsh çəkin; yeni su götürməyin.</li><li>Əvvəl sağ, sonra sol ayağın üstünə barmaq uclarından topuq oynağınadək məsh çəkin. Məshedilən səth rütubətin təsirini qəbul etməlidir.</li></ol><p>Üz və qolların bir dəfə yuyulması vacib, ikinci dəfə müstəhəb, üçüncü dəfə yuyulması haramdır. Ardıcıllığı və fasiləsizliyi qoruyun.</p>':'<ol><li>Niyyət və Bismillah ilə başlayın. Əlləri yuyun; ağıza və buruna su verib təmizləyin.</li><li>Üzü, sonra sağ və sol qolu dirsəklərlə birlikdə yuyun.</li><li>Yaş əllə başa məsh çəkin. Başın ən azı dörddə birinə məsh fərzdir. Qulaqlara məsh edin.</li><li>Sağ, sonra sol ayağı topuqlarla birlikdə yuyun. Barmaq araları quru qalmasın.</li></ol><p>Yuyulan üzvləri üç dəfə yumaq sünnədir; başa məsh bir dəfə edilir. Üzü, qolları, ayaqları bir dəfə tam yumaq və başa məsh dəstəmazın fərzləridir.</p>'}<p>Namazdan əvvəl vaxtı, qibləni, bədən və geyimin təmizliyini yoxlayın. Kişilər ən az göbəkdən dizədək, qadınlar namaz üçün tələb olunan örtünməni təmin etməlidirlər; Hənəfi qaydasında üz, əllər və ayaqlar, Cəfəri qaydasında üz və biləyədək əllər, naməhrəm yoxdursa topuqdan aşağı ayaqlar istisnadır.</p></details>`}
function prayerGuide(){const s=guideState(),j=s.school==='jafari',steps=guideSteps(s);s.step=Math.max(0,Math.min(Number(s.step)||0,steps.length));const done=s.step===steps.length,step=steps[s.step],pct=Math.round(s.step/steps.length*100),school=j?'Cəfəri':'Hənəfi';return head('Namazı öyrən','Addım-addım, öz sürətinizlə')+`<section class="learn-intro"><span>✧ İLK ADDIMDAN SALAMA QƏDƏR</span><h2>İbadətə doğru bir addım.</h2><p>Təlimatı namazdan əvvəl öyrənmək üçün istifadə edin.</p></section><section class="card guide-options"><div class="tabs" role="group" aria-label="Məzhəb seçimi"><button aria-pressed="${!j}" class="${!j?'active':''}" onclick="setGuide('school','hanafi')">Hənəfi <small>Sünni</small></button><button aria-pressed="${j}" class="${j?'active':''}" onclick="setGuide('school','jafari')">Cəfəri <small>Şiə</small></button></div><label for="guidePrayer">Hansı namazı öyrənirsiniz?</label><select id="guidePrayer" onchange="setGuide('prayer',this.value)">${guidePrayers.map(([n,r],i)=>`<option value="${i}" ${s.prayer===i?'selected':''}>${n} · ${r} rükət fərz</option>`).join('')}</select><p class="notice">${j?'Cəfəri qaydası · Sistani hökmləri əsasında.':'Hənəfi qaydası · Diyanet təlimatı əsasında.'} Bu izah səfərdə olmayan şəxsin tək qıldığı gündəlik fərz namazı üçündür; sünnə və vitr namazları daxil deyil.</p>${preparation(j)}</section><section class="card guide-stage" aria-labelledby="stepTitle"><div class="guide-counter"><span>${school} · ${guidePrayers[s.prayer][0]}</span><strong>${done?'Tamamlandı':`${s.step+1} / ${steps.length}`}</strong></div><div class="progress"><div style="width:${done?100:pct}%"></div></div>${done?`<div class="guide-complete"><span>✓</span><h2 id="stepTitle">Təlimatı tamamladınız.</h2><p>Allah ibadətinizi qəbul etsin. Oxunuşları təkrar edə və başqa namazı seçə bilərsiniz.</p><p class="notice">Bu, öyrənmə qeydidir; namaz izləyicisində namaz qılınmış kimi qeyd edilmir.</p><button class="goldbtn" onclick="moveGuide(-${steps.length})">Yenidən başla</button><button class="textbtn" onclick="go('tracker')">Namaz izləyicisinə keç →</button></div>`:`<div class="step-heading"><div><span class="eyebrow">${step.r?step.r+'-Cİ RÜKƏT':'NAMAZDAN ƏVVƏL'}</span><h2 id="stepTitle" tabindex="-1">${step.title}</h2>${step.tag?`<span class="badge">${step.tag}</span>`:''}</div>${posture(step.pose)}</div><p class="step-body">${step.body}</p>${step.rec.map(recitationCard).join('')}<div class="guide-controls"><button class="secondarybtn" onclick="moveGuide(-1)" ${s.step===0?'disabled':''}>← Əvvəlki</button><button class="goldbtn" onclick="moveGuide(1)">${s.step===steps.length-1?'Tamamla ✓':'Növbəti →'}</button></div>`}</section><details class="guide-details card"><summary>Ardıcıllığa ümumi baxış</summary><ol class="step-index">${steps.map((t,i)=>`<li><button onclick="jumpGuide(${i})" ${s.step===i?'aria-current="step"':''}>${t.r?t.r+'. rükət · ':''}${t.title}</button></li>`).join('')}</ol></details><details class="guide-details card"><summary>Oxunuş, qaydalar və mənbələr</summary><p>Latın oxunuşu köməkçidir; ərəb tələffüzünü bilən müəllimdən dinləyərək öyrənin. Şəkillər hərəkəti tanıdan sxemlərdir.</p><p>${j?'Kişilər Sübh, Məğrib və İşanın ilk iki rükətində Fatihə və surəni səsli, Zöhr və İkindidə asta oxuyurlar. Qadınlara səsli oxumaq vacib deyil. Üçüncü və dördüncü rükətdə təsbihat və ya Fatihə asta oxunur. Qunut müstəhəbdir. Səcdədə alın yeməli və geyilməli olmayan, icazəli təbii səthə qoyulur.':'Tək qılan şəxs Zöhr və İkindini asta oxuyur; Sübh, Məğrib və İşanın ilk iki rükətində səsli və ya asta qiraət edə bilər. Hərəkətlərdə tələsməyin. Qadın və kişilərin duruş detallarında fərqlər var; aşağıdakı təsvirli mənbədən baxa bilərsiniz.'}</p><p>Səfər, xəstəlik, camaat namazı və səhv səcdəsi kimi xüsusi hallar bu başlanğıc təlimatına daxil deyil.</p><ul class="source-links">${j?'<li><a href="https://www.sistani.org/english/book/26890/8502/" target="_blank" rel="noopener">Sistani · Namazın hissələri və qaydaları ↗</a></li><li><a href="https://www.sistani.org/english/book/26890/8479/" target="_blank" rel="noopener">Sistani · Dəstəmaz ↗</a></li><li><a href="https://www.sistani.org/english/book/48/2239/" target="_blank" rel="noopener">Təşəhhüd ↗</a> · <a href="https://www.sistani.org/english/book/48/2240/" target="_blank" rel="noopener">Salam ↗</a> · <a href="https://www.sistani.org/english/book/48/2235/" target="_blank" rel="noopener">Səcdə ↗</a></li>':'<li><a href="https://dijital.diyanet.gov.tr/File/Download?id=394&amp;path=namaz_ilmihali.pdf" target="_blank" rel="noopener">Diyanet · Namaz İlmihali, s. 91–100, 144–148, 212–215 ↗</a></li><li><a href="https://dijital.diyanet.gov.tr/File/Download?id=4218&amp;path=4218_1.pdf" target="_blank" rel="noopener">Diyanet · Sübh namazı təlimatı ↗</a></li>'}</ul></details>`}
function moveGuide(delta){const s=guideState();s.step=Math.min(guideSteps(s).length,Math.max(0,(Number(s.step)||0)+delta));save('nur-guide',s);render();document.querySelector('.guide-stage')?.scrollIntoView?.({behavior:'smooth',block:'start'});document.querySelector('#stepTitle')?.focus?.({preventScroll:true})}
function jumpGuide(i){const s=guideState();s.step=i;save('nur-guide',s);render();document.querySelector('.guide-stage')?.scrollIntoView?.({behavior:'smooth',block:'start'})}
